/** Metadata ONLY — deliberately excludes files/solutionFiles/testCode, which are what makes a
 *  ProjectTask heavy. The Build Portal catalog page renders entirely from this array; a task's full
 *  body only loads (via getSeTask() in ./index.ts, a dynamic import) once a learner actually opens it.
 *  At 8 seed tasks this wouldn't matter yet, but the whole point of Phase 0 is proving the shape that
 *  still works once this array has hundreds of entries. */
export interface SeTaskMeta {
  id: string;
  title: string;
  /** one line, catalog-card-only — the full `prompt` (and everything else) lives in the task's own
   *  lazy-loaded module, not here, so the catalog page never has to import 800 tasks' worth of content
   *  just to render a grid of cards. */
  summary: string;
  difficulty: CodeDifficulty;
  language: SeLanguage;
  track: SeTrack;
  category: string;
  /** how many files this task's project has — shown on the card so a learner can gauge scope before opening it. */
  fileCount: number;
  tags?: string[];
}

